function parkingPage(url) {
  const query=url.searchParams.get("tab")==="query";
  const fresh=url.searchParams.get("new")==="1";
  const cancelled=url.searchParams.get("cancelled")==="1";
  if (query) return `<main class="page"><div class="lead"><h1>車位預約</h1><p>選擇日期、時段與可用車位</p></div><div class="seg"><a href="/parking">我的預約</a><a class="on" href="/parking?tab=query">預約查詢</a></div><section class="form-card"><label>停車區域<select class="field"><option>A 棟地下停車場</option><option>B 棟地下停車場</option></select></label><label>日期<input class="field" type="date" value="2026-08-05"></label><label>預約時段<select class="field"><option>09:00–12:00</option><option>13:00–17:00</option><option>18:00–22:00</option></select></label><label>車牌號碼<input class="field" value="ABC-1234"></label></section><div class="section-head"><h2>可用車位</h2><span class="tiny">B2 汽車區</span></div><section class="parking-space-grid"><a class="parking-space" href="/parking/book?id=B2-082&slot=0900">B2-082<small>可預約</small></a><a class="parking-space" href="/parking/book?id=B2-086&slot=0900">B2-086<small>可預約</small></a><span class="parking-space busy">B2-088<small>已預約</small></span><a class="parking-space" href="/parking/book?id=B2-091&slot=0900">B2-091<small>可預約</small></a><a class="parking-space" href="/parking/book?id=B2-095&slot=0900">B2-095<small>可預約</small></a><span class="parking-space busy">B2-099<small>已預約</small></span></section><a class="btn secondary" href="/booking">返回預約中心</a></main>`;
  return `<main class="page"><div class="lead"><h1>車位預約</h1><p>管理臨停車位與登記車牌</p></div>${fresh?`<div class="summary" style="margin-top:14px">✓ 車位 B2-082 已預約成功。</div>`:cancelled?`<div class="summary" style="margin-top:14px">車位 B2-082 預約已取消。</div>`:""}<div class="seg"><a class="on" href="/parking">我的預約</a><a href="/parking?tab=query">預約查詢</a></div><a class="btn primary" href="/parking?tab=query">＋ 預約車位</a><article class="record"><div class="record-head"><div><h3>B2-082 汽車位</h3><p>#PKG-2026-0805-082</p></div><span class="status ${cancelled?"red":"green"}">${cancelled?"已取消":"已預約"}</span></div><p>08/05（三）09:00–12:00</p><p>車牌：ABC-1234 · A 棟地下停車場</p>${cancelled?"":`<div class="record-actions"><a class="btn secondary" href="/parking?tab=query">變更</a><a class="btn danger" href="/parking/cancel">取消</a></div>`}</article><article class="record"><div class="record-head"><div><h3>B1-M026 機車位</h3><p>#PKG-2026-0729-026</p></div><span class="status">已完成</span></div><p>07/29（三）08:30–18:00</p></article><a class="btn secondary" href="/booking">返回預約中心</a></main>`;
}

